package com.constructflow.document.storage;

import java.io.InputStream;

/**
 * Where document bytes live. Metadata stays in PostgreSQL; bytes go to a storage backend behind this
 * interface. {@link LocalFileStorage} is used in development. In production an S3-compatible
 * implementation (e.g. Cloudflare R2, AWS S3) would implement the same three methods.
 *
 * <p>Keys are always generated by the server ({@code orgId/documentId/uuid}), never taken from the
 * client's file name, so a crafted name such as {@code ../../etc/passwd} cannot reach the filesystem.
 */
public interface FileStorage {

    void store(String key, byte[] content);

    InputStream open(String key);

    void delete(String key);
}
